// Coleta os dados de ambos os nós anteriores
const titulos = $('Buscar catálogo completo').all().map(i => i.json);
const calibracao = $('Buscar calibração').all().map(i => i.json);

// Ordena por BSR
const ativos = titulos.filter(t => t.bsr_geral);
ativos.sort((a, b) => a.bsr_geral - b.bsr_geral);

const top5       = ativos.slice(0, 5);
const bottom5    = ativos.slice(-5).reverse();
const criticos   = ativos.filter(t => t.bsr_geral > 100_000);
const total      = titulos.length;
const semBsr     = titulos.filter(t => !t.bsr_geral).length;

// Métricas financeiras agregadas
const totalVendas    = titulos.reduce((s, t) => s + (t.vendas_mes || 0), 0);
const totalKenp      = titulos.reduce((s, t) => s + (t.kenp_mes || 0), 0);
const totalRoyalties = titulos.reduce((s, t) => s + (t.royalties_mes || 0), 0);

// Estimativa de vendas via calibração (soma para todos)
function estimarVendas(bsr, cal) {
  if (!bsr || !cal.length) return null;
  const faixa = cal.find(f => f.bsr_min <= bsr && f.bsr_max >= bsr);
  return faixa ? Math.round(faixa.vendas_diarias_media * 30) : null;
}

// BSR médio do portfólio
const bsrMedio = ativos.length
  ? Math.round(ativos.reduce((s, t) => s + t.bsr_geral, 0) / ativos.length)
  : null;

// Tier distribution
const tiers = {
  top:    ativos.filter(t => t.bsr_geral < 1_000).length,
  otimo:  ativos.filter(t => t.bsr_geral >= 1_000  && t.bsr_geral < 5_000).length,
  bom:    ativos.filter(t => t.bsr_geral >= 5_000  && t.bsr_geral < 20_000).length,
  ok:     ativos.filter(t => t.bsr_geral >= 20_000 && t.bsr_geral < 100_000).length,
  ruim:   ativos.filter(t => t.bsr_geral >= 100_000).length,
};

const semana = (() => {
  const d = new Date();
  const inicio = new Date(d);
  inicio.setDate(d.getDate() - 7);
  return `${inicio.toLocaleDateString('pt-BR')} a ${d.toLocaleDateString('pt-BR')}`;
})();

return [{
  json: {
    semana,
    total,
    sem_bsr: semBsr,
    total_vendas: totalVendas,
    total_kenp: totalKenp,
    total_royalties: totalRoyalties,
    bsr_medio: bsrMedio,
    tiers,
    top5,
    bottom5,
    criticos: criticos.length,
    titulos_ativos: ativos.length,
  }
}];
